def mul(p,q):
    out={}
    for (i,j),v in p.items():
        for (k,l),w in q.items():
            if i+k<=1 and j+l<=1:
                out[i+k,j+l]=out.get((i+k,j+l),0)+v*w
    return {ij:v%2 for ij,v in out.items() if v%2}
